const clean = (value, limit = 200) => typeof value === 'string' ? value.trim().slice(0, limit) : '';
const sessionId = clean($json.session_id, 100);
const requestId = clean($json.request_id, 100) || 'linkedin-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
const emailAddress = clean($json.email_address, 254);
const fullName = clean($json.full_name, 160);
const countryRegion = clean($json.country_region, 100);
const stateProvince = clean($json.state_province, 100);
const cityLocation = clean($json.city_location, 100);
const industry = clean($json.industry, 180);
const normalise = (value) => String(value ?? '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const industryStop = new Set(['and','business','services','service','company','industry','sector','professional']);
const industryTerms = industry
  .toLowerCase()
  .replace(/\band\b/g, ',')
  .replaceAll(';', ',')
  .replaceAll('/', ',')
  .replaceAll('|', ',')
  .split(',')
  .map(normalise)
  .filter((term) => term.length >= 3 && !industryStop.has(term))
  .slice(0, 4);
const paidLookupConfirmed = $json.paid_lookup_confirmed === true;
const emailOk = !emailAddress || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailAddress);
const nameTokens = normalise(fullName).split(' ').filter(Boolean);
const honorificAliases = { dr: 'dr', doctor: 'dr', prof: 'prof', professor: 'prof' };
const requestedHonorific = honorificAliases[nameTokens[0]] ?? '';
const searchName = fullName
  .replace(/^(dr|doctor|mr|mrs|ms|miss|prof|professor)\.?\s+/i, '')
  .replace(/\s+(phd|md|mba|jd|esq)\.?$/i, '')
  .trim();
const australianCapitalRegions = {
  adelaide: 'South Australia', brisbane: 'Queensland', canberra: 'Australian Capital Territory',
  darwin: 'Northern Territory', hobart: 'Tasmania', melbourne: 'Victoria', perth: 'Western Australia',
  sydney: 'New South Wales'
};
const inferredRegion = normalise(countryRegion).includes('australia')
  ? (australianCapitalRegions[normalise(cityLocation)] ?? '')
  : '';
let errorCode = '';
let errorMessage = '';
if (!searchName || searchName.split(/\s+/).length < 2) {
  errorCode = 'FULL_NAME_REQUIRED';
  errorMessage = 'Provide the person\'s first and last name before searching.';
} else if (!emailOk) {
  errorCode = 'INVALID_EMAIL';
  errorMessage = 'The optional work email is not valid.';
} else if (!paidLookupConfirmed) {
  errorCode = 'PAID_LOOKUP_APPROVAL_REQUIRED';
  errorMessage = 'Before searching, explicitly approve one Crustdata person search costing up to 0.30 credits.';
}
const conditions = [{ field: 'basic_profile.name', type: '(.)', value: searchName }];
const localConditions = [];
for (const value of [cityLocation, stateProvince, inferredRegion]) {
  if (value && !localConditions.some((condition) => normalise(condition.value) === normalise(value))) {
    localConditions.push({ field: 'basic_profile.location.full_location', type: '(.)', value });
  }
}
if (localConditions.length === 1) conditions.push(localConditions[0]);
else if (localConditions.length > 1) conditions.push({ op: 'or', conditions: localConditions });
if (countryRegion) conditions.push({ field: 'basic_profile.location.full_location', type: '(.)', value: countryRegion });
const searchBody = {
  filters: conditions.length === 1 ? conditions[0] : { op: 'and', conditions },
  fields: [
    'metadata.updated_at',
    'basic_profile',
    'experience.employment_details.current',
    'social_handles.professional_network_identifier.profile_url'
  ],
  limit: 10
};
const maskedEmail = emailAddress && emailAddress.includes('@')
  ? emailAddress[0] + '***@' + emailAddress.split('@').pop()
  : '';
return { json: {
  valid: errorCode === '', errorCode, errorMessage, sessionId, requestId,
  emailAddress, maskedEmail, fullName, searchName, requestedHonorific,
  countryRegion, stateProvince, cityLocation, inferredRegion,
  industry, industryTerms, paidLookupConfirmed, searchBody, maxCredits: 0.30
} };

const input = $('Validate Lookup Input').first().json;
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
const creditsUsed = Number(headers['x-credits-used'] ?? headers['X-Credits-Used'] ?? 0) || 0;
if (statusCode < 200 || statusCode >= 300) {
  return { json: { response: { ok: false, match_status: 'unavailable', confidence: 'none', score: 0, evidence: [], profile: null, candidates: [], profile_enriched: false, credits_used: creditsUsed, message: 'The professional-data provider was unavailable (HTTP ' + statusCode + '). No automatic retry was made.' } } };
}
const profiles = Array.isArray(body.profiles) ? body.profiles : [];
const normalise = (value) => String(value ?? '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const ignoredNameTokens = new Set(['dr','doctor','mr','mrs','ms','miss','prof','professor','phd','md','mba','jd','esq','fgia','cem']);
const normaliseName = (value) => normalise(value).split(' ').filter((token) => !ignoredNameTokens.has(token)).join(' ');
const wantedName = normaliseName(input.fullName);
const wantedLocation = {
  country: normalise(input.countryRegion),
  state: normalise(input.stateProvince || input.inferredRegion),
  city: normalise(input.cityLocation)
};
const stop = new Set(['and','business','services','service','company','industry','sector','professional']);
const industryTerms = Array.isArray(input.industryTerms)
  ? input.industryTerms.map(normalise).filter((term) => term.length >= 3 && !stop.has(term)).slice(0, 4)
  : String(input.industry ?? '')
      .toLowerCase()
      .replace(/\band\b/g, ',')
      .replaceAll(';', ',')
      .replaceAll('/', ',')
      .replaceAll('|', ',')
      .split(',')
      .map(normalise)
      .filter((term) => term.length >= 3 && !stop.has(term))
      .slice(0, 4);
const linkedinSlug = (value) => {
  const url = String(value ?? '').trim();
  const lower = url.toLowerCase();
  const prefix = 'https://';
  if (!lower.startsWith(prefix)) return '';
  const afterScheme = lower.slice(prefix.length);
  const firstSlash = afterScheme.indexOf('/');
  if (firstSlash <= 0) return '';
  const host = afterScheme.slice(0, firstSlash);
  if (host !== 'linkedin.com' && !host.endsWith('.linkedin.com')) return '';
  const pathAndSuffix = afterScheme.slice(firstSlash);
  if (!pathAndSuffix.startsWith('/in/')) return '';
  const slugAndSuffix = pathAndSuffix.slice(4);
  let stopAt = slugAndSuffix.length;
  for (const separator of ['/', '?', '#']) {
    const position = slugAndSuffix.indexOf(separator);
    if (position >= 0 && position < stopAt) stopAt = position;
  }
  const slug = slugAndSuffix.slice(0, stopAt);
  const allowed = 'abcdefghijklmnopqrstuvwxyz0123456789%_.-';
  return slug && [...slug].every((character) => allowed.includes(character)) ? slug : '';
};
const safeUrl = (value) => linkedinSlug(value) ? String(value ?? '').trim() : '';
const requestedHonorific = String(input.requestedHonorific ?? '');
const honorificMatches = (name) => {
  const tokens = normalise(name).split(' ');
  if (requestedHonorific === 'dr') return tokens.includes('dr') || tokens.includes('doctor');
  if (requestedHonorific === 'prof') return tokens.includes('prof') || tokens.includes('professor');
  return false;
};
const rows = profiles.map((raw) => {
  const basic = raw.basic_profile && typeof raw.basic_profile === 'object' ? raw.basic_profile : {};
  const location = basic.location && typeof basic.location === 'object' ? basic.location : {};
  const current = raw.experience?.employment_details?.current;
  const jobs = Array.isArray(current) ? current : [];
  const primary = jobs.find((job) => job?.is_default === true) ?? jobs[0] ?? {};
  const name = String(basic.name ?? '').trim();
  const professionalNetworkName = String(basic.professional_network_name ?? '').trim();
  const profileUrl = safeUrl(raw.social_handles?.professional_network_identifier?.profile_url);
  const currentCompany = String(primary.name ?? primary.company_name ?? '').trim();
  const currentTitle = String(basic.current_title ?? primary.title ?? '').trim();
  const fullLocation = String(location.full_location ?? location.raw ?? '').trim();
  const structuredLocation = [location.city, location.state, location.country].map((value) => String(value ?? '').trim()).filter(Boolean).join(', ');
  const displayLocation = fullLocation || structuredLocation;
  const industries = [...new Set(jobs.flatMap((job) => [
    ...(Array.isArray(job?.company_industries) ? job.company_industries : []),
    job?.company_professional_network_industry
  ]).map((value) => String(value ?? '').trim()).filter(Boolean))];
  let score = 0;
  const evidence = [];
  const actualName = normaliseName(professionalNetworkName || name);
  if (wantedName && actualName === wantedName) { score += 54; evidence.push('exact core name'); }
  else if (wantedName && actualName && wantedName.split(' ').every((token) => actualName.split(' ').includes(token))) { score += 40; evidence.push('partial name'); }
  if (requestedHonorific && honorificMatches([professionalNetworkName, name].filter(Boolean).join(' '))) { score += 36; evidence.push('requested professional title'); }
  const normalLocation = normalise([fullLocation, structuredLocation].filter(Boolean).join(' '));
  for (const [field, points, label] of [['city',10,'city'],['state',8,input.stateProvince ? 'state or province' : 'metropolitan region'],['country',6,'country or region']]) {
    if (wantedLocation[field] && normalLocation.includes(wantedLocation[field])) { score += points; evidence.push(label); }
  }
  const professionalText = normalise([
    industries.join(' '),
    basic.headline,
    basic.summary,
    currentTitle,
    currentCompany,
    ...jobs.flatMap((job) => [job?.title, job?.name, job?.company_name, job?.function_category, job?.description])
  ].join(' '));
  if (industryTerms.length && industryTerms.some((term) => professionalText.includes(term))) { score += 10; evidence.push('industry or professional context'); }
  const profile = { name: professionalNetworkName || name || null, linkedin_url: profileUrl || null, headline: String(basic.headline ?? '').trim() || null, current_company: currentCompany || null, current_title: currentTitle || null, location: displayLocation || null, industry: industries.join(', ') || null, public_identifier: profileUrl ? linkedinSlug(profileUrl) : null };
  return { score: Math.max(0, Math.min(100, score)), evidence, profile };
}).filter((row) => row.profile.linkedin_url).sort((a, b) => b.score - a.score);
if (rows.length === 0) {
  return { json: { response: { ok: true, match_status: 'not_found', confidence: 'none', score: 0, evidence: [], profile: null, candidates: [], profile_enriched: false, credits_used: creditsUsed, total_matches: Number(body.total_count ?? 0), message: 'No public professional profile with enough usable identity data was returned.' } } };
}
const top = rows[0];
const gap = top.score - (rows[1]?.score ?? 0);
const matched = top.score >= 76 && gap >= 10;
const confidence = matched ? (top.score >= 84 ? 'high' : 'medium') : (top.score >= 60 ? 'low' : 'none');
return { json: { response: { ok: true, match_status: matched ? 'matched' : 'ambiguous', confidence, score: top.score, evidence: top.evidence, profile: matched ? top.profile : null, candidates: matched ? [] : rows.slice(0, 3), profile_enriched: false, credits_used: creditsUsed, total_matches: Number(body.total_count ?? rows.length), returned_matches: profiles.length, message: matched ? 'One likely public professional profile was identified. Verify it before relying on the match.' : 'Several people may match. No profile was selected; add a current employer, role, or more specific location before another paid search.' } } };

const response = $json.response;
const input = $('Validate Lookup Input').first().json;
const error = response?.ok === false ? String(response.error?.message ?? response.message ?? 'Tool failed') : '';
return { json: { occurredAt: new Date().toISOString(), sessionId: input.sessionId, requestId: input.requestId, toolName: 'lookup_linkedin_profile', proposedInput: JSON.stringify({ full_name: input.fullName, email_masked: input.maskedEmail, country_region: input.countryRegion, state_province: input.stateProvince, city_location: input.cityLocation, industry: input.industry, maximum_credits: input.maxCredits }), result: error ? 'error' : String(response.match_status ?? 'ok'), error, response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) response.auditWarning = 'The lookup result could not be written to the local tool audit.';
return { json: response };
